def test_persona_from_dict_preserves_historical_fields():
    """Verify from_dict correctly reconstructs historical fields."""
    original = Persona(
        name="Marcus Aurelius",
        birth_year=121,
        death_year=180,
        family_structure={"birth_order": "eldest", "parent_loss_age": 12},
        religion={"tradition": "Stoic philosophy", "religiosity": 0.9},
        cultural_context={"era": "2nd century CE"},
        life_events={"formative": [{"age": 12, "event": "father's death"}]}
    )
    
    data = original.to_dict()
    reconstructed = Persona.from_dict(data)
    
    assert reconstructed.name == "Marcus Aurelius"
    assert reconstructed.birth_year == 121
    assert reconstructed.death_year == 180
    assert reconstructed.family_structure["birth_order"] == "eldest"
    assert reconstructed.religion["tradition"] == "Stoic philosophy"
    assert reconstructed.cultural_context["era"] == "2nd century CE"
    assert reconstructed.life_events["formative"][0]["age"] == 12


def test_timestamps_auto_populate():
    """Verify created_at and last_updated auto-populate."""
    persona = Persona(name="Test")
    
    assert persona.created_at != ""
    assert persona.last_updated != ""
    assert persona.created_at == persona.last_updated  # Same on creation


def test_update_timestamp():
    """Verify update_timestamp changes last_updated."""
    persona = Persona(name="Test")
    original_timestamp = persona.last_updated
    
    # Simulate passage of time
    import time
    time.sleep(0.01)
    
    persona.update_timestamp()
    assert persona.last_updated != original_timestamp


